// src/components/Admin/AdminCertificateManager.jsx
import React, { useState, useEffect } from 'react';
import { CertificateService } from '../../models/services/certificateService';
import './AdminCertificateManager.css';

const AdminCertificateManager = () => {
  const [certificates, setCertificates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filter, setFilter] = useState('all');

  useEffect(() => {
    loadCertificates();
  }, []);

  const loadCertificates = async () => {
    try {
      const allCertificates = await CertificateService.getAllCertificates(100);
      setCertificates(allCertificates);
    } catch (error) {
      console.error('Erreur chargement certificats:', error);
    } finally {
      setLoading(false);
    }
  };

  const filteredCertificates = certificates.filter(cert => {
    const matchesSearch = cert.studentName.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         cert.courseTitle.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         cert.certificateId.toLowerCase().includes(searchTerm.toLowerCase());
    
    if (filter === 'all') return matchesSearch;
    if (filter === 'recent') {
      const oneWeekAgo = new Date();
      oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);
      return matchesSearch && new Date(cert.createdAt?.toDate()) > oneWeekAgo;
    }
    return matchesSearch;
  });

  const regenerateCertificate = async (certificateId) => {
    if (window.confirm('Regénérer ce certificat?')) {
      try {
        // Implémentation de la regénération
        console.log('Regénération certificat:', certificateId);
        alert('Certificat regénéré avec succès');
      } catch (error) {
        alert('Erreur lors de la regénération');
      }
    }
  };

  if (loading) return <div className="admin-loading">Chargement...</div>;

  return (
    <div className="admin-certificate-manager">
      <div className="admin-header">
        <h1>Gestion des Certificats ({certificates.length})</h1>
        <div className="admin-controls">
          <input
            type="text"
            placeholder="Rechercher par nom, cours ou ID..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="search-input"
          />
          <select value={filter} onChange={(e) => setFilter(e.target.value)}>
            <option value="all">Tous les certificats</option>
            <option value="recent">7 derniers jours</option>
          </select>
          <button onClick={loadCertificates} className="btn-refresh">
            🔄 Actualiser
          </button>
        </div>
      </div>

      <div className="certificates-table-container">
        <table className="certificates-table">
          <thead>
            <tr>
              <th>Étudiant</th>
              <th>Cours</th>
              <th>Score</th>
              <th>Date</th>
              <th>ID Certificat</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredCertificates.map(certificate => (
              <tr key={certificate.id}>
                <td>{certificate.studentName}</td>
                <td>{certificate.courseTitle}</td>
                <td className="score-cell">{certificate.finalScore}%</td>
                <td>
                  {certificate.createdAt?.toDate().toLocaleDateString('fr-FR')}
                </td>
                <td className="certificate-id-cell">
                  <code>{certificate.certificateId}</code>
                </td>
                <td className="actions-cell">
                  <button 
                    onClick={() => window.open(certificate.downloadUrl, '_blank')}
                    className="btn-view"
                  >
                    👁️ Voir
                  </button>
                  <button 
                    onClick={() => regenerateCertificate(certificate.id)}
                    className="btn-regenerate"
                  >
                    🔄 Regénérer
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        
        {filteredCertificates.length === 0 && (
          <div className="no-results">
            Aucun certificat trouvé
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminCertificateManager;
